import { readFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'

import { expect, test, type Page, type Route } from '@playwright/test'

// The whole backend is replaced by interceptors: the test checks what the browser does,
// not PotreeConverter. The octree is generated by scripts/generate-potree-fixture.py.
const FIXTURE_DIR = fileURLToPath(new URL('./fixtures/potree/', import.meta.url))
const ID = 'pc_e2e'
const JOB_ID = 'job_e2e'
const BOUNDS = {
  minX: 500000,
  minY: 2000000,
  minZ: 100,
  maxX: 500097.5,
  maxY: 2000097.5,
  maxZ: 109.75,
}
const POINT_CLOUD = {
  id: ID,
  filename: 'survey.las',
  status: 'ready',
  metadata: { pointCount: 1600, bounds: BOUNDS, crs: 'EPSG:32648' },
}

function json(route: Route, body: unknown, status = 200) {
  return route.fulfill({ status, json: body })
}

// Potree reads octree.bin with Range requests.
async function serveViewerFile(route: Route, name: string) {
  const body = await readFile(`${FIXTURE_DIR}${name}`).catch(() => null)
  if (!body) return route.fulfill({ status: 404, json: { error: { message: 'No such file' } } })

  const contentType = name.endsWith('.json') ? 'application/json' : 'application/octet-stream'
  const range = /^bytes=(\d+)-(\d*)$/.exec(route.request().headers()['range'] ?? '')
  if (!range) return route.fulfill({ status: 200, body, contentType })

  const start = Number(range[1])
  const end = range[2] ? Math.min(Number(range[2]), body.length - 1) : body.length - 1
  return route.fulfill({
    status: 206,
    body: body.subarray(start, end + 1),
    headers: {
      'content-type': contentType,
      'content-range': `bytes ${start}-${end}/${body.length}`,
    },
  })
}

async function mockBackend(page: Page) {
  let polls = 0

  await page.route('**/api/upload', (route) => json(route, POINT_CLOUD, 201))
  await page.route(`**/api/pointcloud/${ID}/convert`, (route) =>
    json(
      route,
      { id: JOB_ID, type: 'convert', state: 'queued', progress: 0, resultId: null, error: null },
      202,
    ),
  )
  await page.route(`**/api/job/${JOB_ID}`, (route) => {
    polls += 1
    return json(
      route,
      polls < 2
        ? {
            id: JOB_ID,
            type: 'convert',
            state: 'running',
            progress: 40,
            resultId: null,
            error: null,
          }
        : {
            id: JOB_ID,
            type: 'convert',
            state: 'succeeded',
            progress: 100,
            resultId: ID,
            error: null,
          },
    )
  })
  await page.route(`**/api/pointcloud/${ID}`, (route) =>
    json(route, {
      ...POINT_CLOUD,
      viewerUrl: `/api/pointcloud/${ID}/viewer/metadata.json`,
      sourceId: null,
    }),
  )
  await page.route(`**/api/pointcloud/${ID}/viewer/*`, (route) =>
    serveViewerFile(route, new URL(route.request().url()).pathname.split('/').pop() ?? ''),
  )
}

function readNumbers(text: string): number[] {
  return text.split(',').map((part) => Number(part.trim()))
}

test('upload, view and measure a point cloud', async ({ page }) => {
  await mockBackend(page)

  // Upload and conversion
  await page.goto('/upload')
  await page.getByLabel('Point cloud file (.las, .laz)').setInputFiles({
    name: 'survey.las',
    mimeType: 'application/octet-stream',
    buffer: Buffer.from('LASF-placeholder'),
  })
  await page.getByRole('button', { name: 'Upload' }).click()
  await expect(page.getByRole('progressbar', { name: 'Conversion progress' })).toBeVisible()
  await expect(page.getByText(`Conversion complete for survey.las (ID: ${ID}).`)).toBeVisible()

  // View: the upload page does not link to the viewer yet, so open it by ID.
  await page.goto(`/viewer/${ID}`)
  await expect(page.getByRole('heading', { name: 'Viewer' })).toBeVisible()
  const canvas = page.locator('.viewer-canvas canvas')
  await expect(canvas).toBeVisible()

  // Everything from here on must only read data.
  const writes: string[] = []
  page.on('request', (request) => {
    if (request.method() !== 'GET') writes.push(`${request.method()} ${request.url()}`)
  })

  // Measure. Points load asynchronously, so keep clicking the middle of the cloud until
  // Potree has something to pick.
  await page.getByRole('button', { name: 'Measure', exact: true }).click()
  const box = (await canvas.boundingBox())!
  const first = { x: box.width * 0.5, y: box.height * 0.5 }
  const second = { x: box.width * 0.6, y: box.height * 0.5 }
  const results = page.locator('.measure-panel [role="status"]')

  await expect(async () => {
    await canvas.click({ position: first, timeout: 1000 })
    await expect(results).toContainText('X', { timeout: 1000 })
  }).toPass({ timeout: 30_000 })

  const pointText = (label: string) =>
    results.locator(`dt:text-is("${label}") + dd`).textContent() as Promise<string>
  const x = Number(await pointText('X'))
  const y = Number(await pointText('Y'))
  const z = Number(await pointText('Z'))
  expect(x).toBeGreaterThanOrEqual(BOUNDS.minX)
  expect(x).toBeLessThanOrEqual(BOUNDS.maxX)
  expect(y).toBeGreaterThanOrEqual(BOUNDS.minY)
  expect(y).toBeLessThanOrEqual(BOUNDS.maxY)
  // The fixture is a plane that rises 0.1 m per metre in x.
  expect(z).toBeCloseTo(BOUNDS.minZ + (x - BOUNDS.minX) * 0.1, 1)

  await canvas.click({ position: second })
  await expect(results.getByText('Distance', { exact: true })).toBeVisible()

  const [fromX, fromY, fromZ] = readNumbers(await pointText('From'))
  const [toX, toY, toZ] = readNumbers(await pointText('To'))
  expect([fromX, fromY, fromZ]).toEqual([x, y, z])
  const dx = toX - fromX
  const dy = toY - fromY
  const dz = toZ - fromZ

  const metres = async (label: string) => Number((await pointText(label)).replace(/\s*m$/, ''))
  const distance = await metres('Distance')
  const horizontal = await metres('Horizontal')
  const vertical = await metres('Vertical')
  expect(distance).toBeGreaterThan(1)
  expect(distance).toBeCloseTo(Math.hypot(dx, dy, dz), 2)
  expect(horizontal).toBeCloseTo(Math.hypot(dx, dy), 2)
  expect(vertical).toBeCloseTo(Math.abs(dz), 2)

  // Clearing asks first and leaves the data untouched.
  await page.getByRole('button', { name: 'Clear measurement' }).click()
  await page.getByRole('button', { name: 'Delete' }).click()
  await expect(results.getByText('Distance', { exact: true })).toBeHidden()
  expect(writes).toEqual([])
})
